const crypto = require('crypto');

function requestId(req, res, next) {
  const id = crypto.randomUUID();
  req.id = id;
  res.set('X-Request-Id', id);
  next();
}

function rateLimiter({ windowMs = 60000, maxRequests = 10 } = {}) {
  const clients = new Map();

  // Periyodik temizlik
  setInterval(() => {
    const now = Date.now();
    for (const [key, value] of clients) {
      if (now > value.resetTime) clients.delete(key);
    }
  }, windowMs);

  return (req, res, next) => {
    const ip = req.ip || req.connection.remoteAddress;
    const now = Date.now();
    const client = clients.get(ip);

    if (!client || now > client.resetTime) {
      clients.set(ip, { count: 1, resetTime: now + windowMs });
      return next();
    }

    client.count++;

    if (client.count > maxRequests) {
      return res.status(429).json({
        error: 'Rate limit aşıldı. Lütfen daha sonra tekrar deneyin.',
      });
    }

    next();
  };
}

function apiKeyAuth(validKeys) {
  return (req, res, next) => {
    let key = null;

    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      key = authHeader.slice(7);
    }

    if (!key) {
      key = req.headers['x-api-key'];
    }

    if (!key) {
      return res.status(401).json({ error: 'API key gerekli' });
    }

    if (!validKeys.includes(key)) {
      return res.status(401).json({ error: 'Geçersiz API key' });
    }

    next();
  };
}

module.exports = { requestId, rateLimiter, apiKeyAuth };
